def apply_async(self, entry, producer=None, advance=True, **kwargs):
    # Update time-stamps and run counts before we actually execute,
    # so we have that done if an exception is raised (doesn't schedule
    # forever.)
    entry = self.reserve(entry) if advance else entry
    task = self.app.tasks.get(entry.task)

    try:
        entry_args = self._evaluate_entry_args(entry.args)
        entry_kwargs = self._evaluate_entry_kwargs(entry.kwargs)

        self.send_task(entry, entry_args, entry_kwargs, task, producer)
    except Exception as exc:  # pylint: disable=broad-except
        reraise(SchedulingError, SchedulingError(
            "Couldn't apply scheduled task {0.name}: {exc}".format(
                entry, exc=exc)), sys.exc_info()[2])
    finally:
        self._tasks_since_sync += 1
        if self.should_sync():
            self._do_sync()

def _evaluate_entry_args(entry_args):
    if not entry_args:
        return []
    return [v() if isinstance(v, BeatLazyFunc) else v for v in entry_args]

def _evaluate_entry_kwargs(entry_kwargs):
    if not entry_kwargs:
        return {}
    return {k: v() if isinstance(v, BeatLazyFunc) else v for k, v in entry_kwargs}

# Repurpose existing function
def send_task(self, entry, entry_args, entry_kwargs, task, producer):
        if task:
            return task.apply_async(
                entry_args, entry_kwargs,
                producer=producer,
                **entry.options
            )
        else:
            return self.app.send_task(
                entry.task,
                entry_args,
                entry_kwargs,
                producer=producer,
                **entry.options
            )
